#include <bits/stdc++.h>

using namespace std;

int main() {
    int n, d;
    string s;
    cin >> n >> d >> s;
    for (int i = 0; i < d; i++) {
        for (int j = n - 1; j >= 0; j--) {
            if (s[j] == '@') {
                s[j] = '.';
                break;
            }
        }
    }
    cout << s << endl;
}

n, d = map(int, input().split())
s = input()
for i in range(d):
    for j in range(n):
        if s[n - 1 - j] == '@':
            s = s[:n - 1 - j] + "." + s[n - j:]
            break
